// not to the policy total.
function itemSurcharges(item: Item): number {
  const listedBasePremium = BASE_PREMIUMS[item.type];
  let surcharges = 0;
  if (item.cursed === true) {
    surcharges += listedBasePremium * CURSE_SURCHARGE_RATE;
  }
  if (isHighlyEnchanted(item)) {
    surcharges += listedBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
  }
  return surcharges;
}

// The spec's "policy base premium": the sum of all item base premiums,
// before any item-specific or policy-wide modifier.
function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of groupAlikeItems(items)) {
    total += basePremiumForAlikeGroup(type, count);
  }
  return total;
}

function totalItemSurcharges(items: Item[]): number {
  return items.reduce((total, item) => total + itemSurcharges(item), 0);
}

// The figure policy-wide modifiers are applied to: the policy base premium
// plus every item's own risk surcharges.
function premiumBeforePolicyModifiers(items: Item[]): number {
  return policyBasePremium(items) + totalItemSurcharges(items);
}

function applyPolicyModifiers(basePremium: number): number {
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return basePremium + firstInsuranceSurcharge;

