function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + listedInsuranceValue(item.type), 0);
}

function roundPayoutInMHPCOsFavour(payout: number): number {
  return Math.floor(payout);
}

// A deductible applies per damage event, so each damaged item is reimbursed
// separately before the policy cap is applied.
function reimbursementForDamage(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

function reimbursementForIncident(incident: Incident): number {
  return incident.damages.reduce((total, damage) => total + reimbursementForDamage(damage), 0);
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

interface Policy {
  items: Item[];
  remainingCap: number;
}

function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM };
}

// The cap decision, independent of which claim clauses produced the
// reimbursement: MHPCO never pays more than the policy's remaining cap, and
// whatever it pays is consumed from that cap.
function payoutAllowedByCap(reimbursement: number, remainingCap: number): ClaimResult {
  const payout = roundPayoutInMHPCOsFavour(Math.min(reimbursement, remainingCap));
  return { payout, remainingCap: remainingCap - payout };
}

// Settling a claim composes two independently changing decisions: what the
// claim clauses reimburse, and how much of that the policy cap still allows.
function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  return payoutAllowedByCap(reimbursementForIncident(incident), policy.remainingCap);
}

// Scenario bookkeeping, not a claim-office rule: a claim step names its policy
// by the zero-based index of the quote step that opened it, and the customer's
// contract history grows as the scenario concludes contracts.
class PolicyRegister {
  private readonly byOpeningStep = new Map<number, Policy>();
  private concluded = 0;

  get contractsConcluded(): number {
    return this.concluded;
  }

  record(openingStep: number, policy: Policy): void {
    this.byOpeningStep.set(openingStep, policy);
    this.concluded += 1;
  }

  // Owns the policy's running cap: settling a claim against a registered policy
  // is the only way its remaining cap changes.
  settleAgainst(openingStep: number, incident: Incident): ClaimResult {
    const policy = this.policyOpenedBy(openingStep);
    const settlement = settleClaim(policy, incident);
    policy.remainingCap = settlement.remainingCap;
    return settlement;
  }

  private policyOpenedBy(openingStep: number): Policy {
    const policy = this.byOpeningStep.get(openingStep);
    if (policy === undefined) {
      throw new Error(`claim refers to step ${String(openingStep)}, which created no policy`);
    }
    return policy;
  }
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {

