python3 - <<'PY'
p='src/claim-office.ts'
s=open(p).read()
old_inc=s[s.index('function reimbursementForIncident'):s.index('export interface Damage')]
new_inc='''// Each damage entry is a separate damaged item, so a policy covering one sword
// cannot absorb two sword damages: every entry claims its own insured item.
function reimbursementForIncident(items: Item[], incident: Incident): number {
  const uncovered = [...items];
  return incident.damages.reduce(
    (total, damage) => total + reimbursementForDamage(claimDamagedItem(uncovered, damage), damage),
    0,
  );
}

function claimDamagedItem(uncovered: Item[], damage: Damage): Item {
  const index = uncovered.findIndex((candidate) => candidate.type === damage.itemType);
  if (index === -1) {
    throw new Error(`the policy does not cover a damaged ${damage.itemType}`);
  }
  return uncovered.splice(index, 1)[0];
}

'''
s=s.replace(old_inc,new_inc)
open(p,'w').write(s)
